export const b1Objectives = defineObjectives("b1", [
  [1,"gram","g086","Pasados del relato: escena, hechos y balance","Puedo contar una experiencia eligiendo el imperfecto para la escena y las costumbres, el indefinido para los hechos cerrados y el perfecto compuesto para el balance que llega hasta hoy.",["a2.gram.g045","a2.gram.g049","a2.gram.g050"],{"related":["/past-b1"]}],
  [1,"gram","g087","Pluscuamperfecto: lo anterior a otro pasado","Puedo formar el pluscuamperfecto y usarlo para presentar un hecho anterior a otro momento pasado, una causa anterior o algo que descubrí.",["b1.gram.g086","a2.gram.g046"],{"related":["/sistema-verbal/preterito-pluscuamperfecto-indicativo"]}],
  [1,"voc","w01-mudanza-piso","Mudanza y piso compartido","Puedo hablar de una mudanza y de la vida en un piso compartido: fianza, empaquetar, alquilar una furgoneta, echar una mano, instalarse, repartir las tareas.",["b1.gram.g086"]],
  [1,"pron","w01-acento-pasado","Acento que distingue presente e indefinido","Puedo distinguir de oído y pronunciar pares como «compro / compró» y decir «había» con sus tres sílabas.",["b1.gram.g086"]],
  [1,"lis","w01-dia-mudanza","Escuchar el relato de una mudanza","Puedo seguir una conversación en la que alguien cuenta los retrasos de una mudanza y reconocer sus causas y lo que había pasado antes.",["b1.gram.g087"]],
  [1,"read","w01-blog-primer-mes","Leer un blog sobre el primer mes en una ciudad","Puedo entender una entrada de blog sobre la llegada a una ciudad nueva y situar cada dato antes, durante o después del primer mes.",["b1.gram.g086","b1.gram.g087"]],
  [1,"wri","w01-correo-llegada","Correo sobre una mudanza o una llegada","Puedo escribir un correo de 140 a 180 palabras que cuente una mudanza con escena, hechos, antecedentes y balance.",["b1.gram.g087","b1.disc.w01-orden-relato","b1.voc.w01-mudanza-piso"]],
  [1,"spk","w01-dia-al-reves","Contar un día que salió al revés","Puedo contar durante dos minutos un día complicado y responder a preguntas aclarando qué había pasado antes.",["b1.fun.w01-explicar-lo-ocurrido"]],
  [1,"fun","w01-explicar-lo-ocurrido","Explicar y justificar lo ocurrido","Puedo explicar por qué pasó algo, disculparme o justificarme con una causa anterior y proponer una solución.",["b1.gram.g087"]],
  [1,"disc","w01-orden-relato","Ordenar un relato: escena, giro, antecedente y balance","Puedo organizar un relato en escena, giro, antecedente y balance, y marcar las partes con mientras, de repente, cuando y desde entonces.",["b1.gram.g086","b1.gram.g087"]],
  [2,"gram","g088","Presente de subjuntivo: formación y usos esenciales","Puedo formar el presente de subjuntivo de verbos regulares e irregulares (incluidos sea, esté, vaya, haya, sepa y dé) y usarlo para algo que todavía no es un hecho, como un deseo o un objetivo con para que.",["a2.gram.g058","a2.gram.g059"],{"related":["/sistema-verbal/presente-de-subjuntivo"]}],
  [2,"gram","g089","Deseos: querer que, esperar que, ojalá","Puedo expresar deseos para mí con infinitivo y para otras personas con que + subjuntivo, usar ojalá y despedirme con ¡que + subjuntivo!",["b1.gram.g088"],{"related":["/gramatica/deseos-querer-que-esperar-que-ojala"]}],
  [2,"voc","w02-abrir-negocio","Abrir un negocio y desear suerte","Puedo hablar de la apertura de un negocio pequeño (local, letrero, vitrina, inauguración, socio) y usar fórmulas para desear suerte.",["b1.gram.g089"]],
  [2,"pron","w02-vocal-modo","La vocal final que cambia el modo","Puedo oír y pronunciar con claridad la vocal final que distingue indicativo y subjuntivo (habla / hable) y el acento de esté.",["b1.gram.g088"]],
  [2,"lis","w02-preparar-apertura","Escuchar cómo se reparten tareas antes de una apertura","Puedo seguir una conversación en la que dos personas reparten tareas y expresan deseos, e identificar quién tiene que hacer cada cosa.",["b1.gram.g089"]],
  [2,"read","w02-noticia-barrio","Leer una noticia de un boletín de barrio","Puedo entender una noticia breve sobre un negocio nuevo y relacionar a cada persona con su deseo.",["b1.gram.g088","b1.gram.g089"]],
  [2,"wri","w02-mensaje-deseos","Mensaje de buenos deseos","Puedo escribir un mensaje de 130 a 170 palabras para alguien que empieza algo nuevo, con un recuerdo y al menos cuatro deseos con formas distintas.",["b1.gram.g089","b1.disc.w02-mensaje-ocasion"]],
  [2,"spk","w02-brindis","Un brindis por un comienzo","Puedo hacer un brindis de dos minutos con un recuerdo y varios deseos, y repartir tareas por teléfono negociando quién hace qué.",["b1.fun.w02-expresar-deseos"]],
  [2,"fun","w02-expresar-deseos","Expresar deseos y pedir cosas","Puedo expresar deseos para mí y para otras personas, pedir que alguien haga algo y responder con un deseo corto adecuado a la situación.",["b1.gram.g089"]],
  [2,"disc","w02-mensaje-ocasion","Organizar un mensaje para una ocasión especial","Puedo organizar un mensaje de ocasión en saludo, recuerdo compartido, deseos variados y despedida.",["b1.gram.g089"]],
  [3,"gram","g090","Recomendaciones: sugerir que, aconsejar que","Puedo dar consejos y hacer peticiones con recomendar, aconsejar, sugerir y pedir + que + subjuntivo o + infinitivo, y distinguir decir que como información o como orden.",["b1.gram.g088","b1.gram.g089"],{"related":["/gramatica/recomendaciones-sugerir-que-aconsejar-que"]}],
  [3,"gram","g091","Valoraciones: es importante que, es bueno que","Puedo valorar la acción de alguien con es importante, es una pena o me parece bien + que + subjuntivo, generalizar con infinitivo y distinguirlo de es verdad o está claro + indicativo.",["b1.gram.g088"],{"related":["/gramatica/valoraciones-es-importante-que-es-bueno"]}],
  [3,"gram","g092","Emociones y reacciones con que + subjuntivo","Puedo reaccionar ante lo que hacen otros con me alegra, me molesta o me preocupa que, estar harto de que, sentir que y ¡qué pena que…!, y usar el infinitivo cuando siento y actúo yo.",["b1.gram.g088","a2.gram.g062"],{"related":["/gramatica/emociones-y-reacciones-con-que-subjuntivo"]}],
  [3,"voc","w03-huerto-vecinal","Huerto vecinal y vida asociativa","Puedo hablar de un huerto vecinal y de la vida de una asociación: parcela, sembrar, regar, cosecha, plaga, asamblea, cuota, turno de riego.",["b1.gram.g090"]],
  [3,"pron","w03-g-suave-fuerte","G suave y sonido fuerte en el subjuntivo","Puedo distinguir de oído y pronunciar formas como riegue y recoja, y escribir gu o j según el sonido que conserva el verbo.",["b1.gram.g088"]],
  [3,"lis","w03-asamblea-huerto","Escuchar una asamblea vecinal","Puedo seguir una asamblea con tres participantes e identificar consejos, quejas, valoraciones y propuestas.",["b1.gram.g090","b1.gram.g092"]],
  [3,"read","w03-carta-socios","Leer una carta informativa de una asociación","Puedo entender una carta a los socios de una asociación y distinguir en ella alegrías, preocupaciones y peticiones.",["b1.gram.g091","b1.gram.g092"]],
  [3,"wri","w03-correo-asociacion","Correo a la asociación de vecinos","Puedo escribir un correo de 140 a 180 palabras sobre un espacio común con emociones, valoraciones y al menos tres recomendaciones.",["b1.gram.g090","b1.gram.g091","b1.gram.g092","b1.disc.w03-queja-constructiva"]],
  [3,"spk","w03-propuesta-vecinal","Presentar una propuesta en una reunión de vecinos","Puedo presentar durante dos minutos una propuesta para un espacio común y responder a un vecino que se queja negociando una solución.",["b1.fun.w03-aconsejar-reaccionar"]],
  [3,"fun","w03-aconsejar-reaccionar","Aconsejar, valorar y reaccionar","Puedo aconsejar a alguien, valorar una situación y reaccionar a una noticia con la emoción adecuada.",["b1.gram.g090","b1.gram.g091","b1.gram.g092"]],
  [3,"disc","w03-queja-constructiva","Estructurar una queja constructiva","Puedo organizar una queja constructiva: lo positivo primero, el problema con su valoración y después propuestas concretas.",["b1.gram.g091","b1.gram.g092"]],
  [4,"gram","g093","Opinión afirmativa frente a opinión negada","Puedo afirmar mi opinión con creo que, pienso que o me parece que + indicativo, negarla con no creo que + subjuntivo, buscar acuerdo con ¿no crees que…? y corregir una interpretación con no es que…, es que…",["b1.gram.g088","b1.gram.g091"],{"related":["/gramatica/opinion-afirmativa-frente-a-opinion-negada"]}],
  [4,"gram","g094","Duda, posibilidad y certeza en enunciados","Puedo graduar lo que digo entre la certeza (seguro que, está claro que), la posibilidad (a lo mejor, es posible que, puede que, quizás) y la duda (dudo que), con el modo que pide cada expresión.",["b1.gram.g093"],{"related":["/gramatica/duda-posibilidad-y-certeza-en-enunciados"]}],
  [4,"voc","w04-organizacion-trabajo","Organización del trabajo y debate","Puedo hablar de cómo se organiza el trabajo (jornada laboral, teletrabajo, plan piloto, rendir, conciliar) y usar expresiones para debatir una propuesta.",["b1.gram.g093"]],
  [4,"pron","w04-pregunta-afirmacion","Melodía de pregunta y de afirmación","Puedo distinguir de oído una pregunta de sí o no de una afirmación con las mismas palabras y producir la subida o la bajada final.",["b1.gram.g093"]],
  [4,"lis","w04-reunion-equipo","Escuchar una reunión de equipo","Puedo seguir una reunión en la que tres personas debaten una propuesta y reconocer la postura, las razones y el grado de seguridad de cada una.",["b1.gram.g093","b1.gram.g094"]],
  [4,"read","w04-columna-opinion","Leer una columna de opinión","Puedo entender una columna de opinión y distinguir lo que la autora afirma, lo que presenta como posible y lo que niega.",["b1.gram.g094"]],
  [4,"wri","w04-comentario-foro","Comentario de opinión en un foro","Puedo escribir un comentario de 140 a 180 palabras que defienda una postura, rechace una idea contraria y gradúe la seguridad sobre sus consecuencias.",["b1.gram.g093","b1.gram.g094","b1.disc.w04-argumentar-postura"]],
  [4,"spk","w04-debate-propuesta","Defender una postura y responder objeciones","Puedo defender una postura durante dos minutos y, en interacción, preguntar opiniones, responder objeciones y aclarar malentendidos.",["b1.fun.w04-opinar-matizar"]],
  [4,"fun","w04-opinar-matizar","Opinar, matizar y buscar acuerdo","Puedo dar y pedir opiniones, matizarlas según mi seguridad y buscar el acuerdo de mi interlocutor.",["b1.gram.g093","b1.gram.g094"]],
  [4,"disc","w04-argumentar-postura","Organizar una argumentación breve","Puedo organizar una argumentación breve en postura, argumentos, rechazo de una idea contraria y conclusión con una posibilidad.",["b1.gram.g093"]],
  [5,"gram","g095","Infinitivo o que + subjuntivo: mismo sujeto / otro","Puedo elegir el infinitivo cuando la misma persona hace las dos acciones y que + subjuntivo cuando es otra persona, y usar permitir, prohibir, dejar y obligar a con pronombre e infinitivo.",["b1.gram.g089","b1.gram.g092"],{"related":["/gramatica/infinitivo-o-que-subjuntivo-mismo-sujeto"]}],
  [5,"gram","g096","Imperativo y peticiones indirectas con subjuntivo","Puedo dar órdenes afirmativas y negativas con todas las personas, colocar bien los pronombres y pasar una orden a otra persona con dile que, dice que o me pide que + subjuntivo.",["b1.gram.g088","b1.gram.g090","a2.gram.g058","a2.gram.g065"],{"related":["/gramatica/imperativo-y-peticiones-indirectas-con-subjuntivo"]}],
  [5,"voc","w05-voluntariado-acogida","Voluntariado, familia de acogida y Andes","Puedo hablar de un voluntariado con familia de acogida en los Andes (páramo, soroche, madrugar, dejar un recado, hacer caso) y reconocer expresiones ecuatorianas como ¿me regala…?, ya mismo y ¡achachay!",["b1.gram.g096"]],
  [5,"pron","w05-acento-imperativo","El acento en el imperativo con pronombres","Puedo pronunciar con su acento órdenes con pronombres pegados (siéntese, dímelo) y distinguirlas de oído de las negativas (no se siente, no me lo digas).",["b1.gram.g096"]],
  [5,"lis","w05-recados-familia","Escuchar recados transmitidos","Puedo seguir una conversación en la que alguien transmite recados de otra persona, da consejos y recuerda el pasado, y reconocer qué tiene que hacer cada uno.",["b1.gram.g095","b1.gram.g096"]],
  [5,"read","w05-blog-voluntaria","Leer un blog de viaje integrado","Puedo leer una entrada de blog que combina relato, deseos, consejos y opiniones, y relacionar cada fragmento con la estructura que usa.",["b1.gram.g095","b1.rev.w05-semanas-1-5"]],
  [5,"wri","w05-correo-consejos","Correo con experiencia, instrucciones y recados","Puedo escribir un correo de 150 a 190 palabras que cuente una llegada, dé instrucciones y consejos, transmita un recado y termine con una valoración y un deseo.",["b1.gram.g095","b1.gram.g096","b1.disc.w05-correo-experiencia"]],
  [5,"spk","w05-pasar-recados","Contar una experiencia y pasar recados","Puedo contar durante dos minutos una experiencia de llegada con consejos y, en interacción, transmitir recados de otras personas y aclarar los que no se entienden.",["b1.fun.w05-dar-transmitir-ordenes"]],
  [5,"fun","w05-dar-transmitir-ordenes","Dar y transmitir órdenes y peticiones","Puedo dar instrucciones directas con el imperativo y transmitir órdenes y peticiones de otros con que + subjuntivo.",["b1.gram.g096"]],
  [5,"disc","w05-correo-experiencia","Organizar un correo de experiencia y consejos","Puedo organizar un correo en saludo, relato de la experiencia, consejos e instrucciones, recado y valoración, y cierre con un deseo.",["b1.gram.g095","b1.gram.g096"]],
  [5,"rev","w05-semanas-1-5","Checkpoint 1: semanas 1 a 5","Puedo contar una experiencia con escena, hechos y antecedentes, y combinarla con deseos, consejos, valoraciones, emociones, opiniones con distinto grado de certeza, la elección entre infinitivo y que + subjuntivo, y órdenes directas y transmitidas.",["b1.gram.g086","b1.gram.g087","b1.gram.g088","b1.gram.g089","b1.gram.g090","b1.gram.g091","b1.gram.g092","b1.gram.g093","b1.gram.g094","b1.gram.g095","b1.gram.g096"]],
  [6,"gram","g097","Perfecto de subjuntivo: valorar ahora lo que ya pasó","Puedo reaccionar, dudar o considerar una posibilidad sobre algo que ya ha ocurrido con «haya + participio», y distinguirlo del presente de subjuntivo y del perfecto de indicativo.",["b1.gram.g088","b1.gram.g092"],{"related":["/sistema-verbal/preterito-perfecto-subjuntivo"]}],
  [6,"gram","g098","Oraciones temporales referidas al futuro","Puedo situar acciones futuras con «cuando», «en cuanto», «hasta que», «mientras», «antes de que» y «después de que» + subjuntivo, y usar indicativo para hábitos y hechos pasados.",["b1.gram.g088"],{"related":["/gramatica/temporales-futuras-cuando-en-cuanto-hasta"]}],
  [6,"voc","w06-teatro-estreno","Teatro, ensayos y noche de estreno","Puedo hablar de una puesta en escena con palabras como ensayo general, elenco, telón, taquilla, vestuario, salir a escena y entradas agotadas.",["b1.gram.g098"]],
  [6,"pron","w06-h-muda-enlace","La h muda y el enlace en «que haya»","Puedo distinguir de oído «que ha» de «que haya» y «han» de «hayan», y enlazar «que_haya» sin cortar entre palabras.",["b1.gram.g097"]],
  [6,"lis","w06-ensayo-general","Escuchar el final de un ensayo general","Puedo seguir la conversación de una directora y su equipo tras un ensayo general y separar lo que valoran de lo que planean para el estreno.",["b1.gram.g097","b1.gram.g098"]],
  [6,"read","w06-bitacora-compania","Leer la bitácora de una compañía de teatro","Puedo entender una entrada de blog en la que una compañía repasa su semana y anuncia los pasos hasta el estreno.",["b1.gram.g097","b1.gram.g098"]],
  [6,"wri","w06-mensaje-elenco","Mensaje al elenco antes del estreno","Puedo escribir un mensaje de unas 150 palabras que valore lo que el grupo ya ha hecho y organice los pasos del día siguiente.",["b1.disc.w06-secuencia-pasos","b1.fun.w06-valorar-coordinar"]],
  [6,"spk","w06-arenga-preguntas","Arenga antes de la función y respuesta a dudas","Puedo dar una breve arenga de dos minutos al equipo y responder a las preguntas de una persona nueva sobre lo que pasará durante la función.",["b1.fun.w06-valorar-coordinar"]],
  [6,"fun","w06-valorar-coordinar","Valorar novedades y coordinar lo que sigue","Puedo reaccionar a novedades del equipo («qué bien que hayan…», «no creo que haya…») y coordinar qué hará cada persona y cuándo.",["b1.gram.g097","b1.gram.g098"]],
  [6,"disc","w06-secuencia-pasos","Ordenar pasos con marcadores temporales","Puedo encadenar instrucciones en orden con «antes de que», «en cuanto», «mientras», «hasta que» y «después de que» sin repetir siempre «cuando».",["b1.gram.g098"]],
  [7,"gram","g099","Expresar finalidad: para, para que, a fin de que","Puedo explicar para qué hago algo con «para» + infinitivo si el sujeto es el mismo y con «para que» o «a fin de que» + subjuntivo si es otro, y preguntar «¿para qué…?» con indicativo.",["b1.gram.g095"],{"related":["/gramatica/finales-para-que-a-fin-de"]}],
  [7,"gram","g100","Relativas con «que» y «quien»: identificar, añadir y buscar","Puedo identificar personas, cosas y lugares con «que», añadir un dato entre comas con «quien» o «que», y elegir indicativo si el antecedente es conocido y subjuntivo si lo estoy buscando.",["b1.gram.g088"],{"related":["/la-persona-que-tengo-en-mente"]}],
  [7,"voc","w07-vivienda-alquiler","Buscar vivienda y alquilar","Puedo describir la vivienda que busco y entender un anuncio con palabras como inmobiliaria, garantía, gastos comunes, dormitorio, luminoso y amueblado.",["b1.gram.g100"]],
  [7,"pron","w07-pausa-relativa","Pausas en las relativas que añaden un dato","Puedo oír si una relativa va entre pausas (dato añadido) o sin pausas (identifica) y marcar esa diferencia al hablar.",["b1.gram.g100"]],
  [7,"lis","w07-llamada-inmobiliaria","Una llamada a una inmobiliaria","Puedo seguir una llamada en la que una clienta explica qué vivienda busca y para qué la necesita, y anotar los requisitos y las ofertas.",["b1.gram.g099","b1.gram.g100"]],
  [7,"read","w07-foro-recien-llegados","Un foro de recién llegados","Puedo entender una consulta en un foro de recién llegados y las respuestas, y distinguir lo que alguien busca de lo que otra persona ya conoce.",["b1.gram.g100"]],
  [7,"wri","w07-anuncio-busqueda","Anuncio para buscar a alguien","Puedo escribir un anuncio de unas 150 palabras que describa a la persona que busco y explique para qué la necesito.",["b1.fun.w07-pedir-requisitos","b1.disc.w07-requisito-finalidad"]],
  [7,"spk","w07-describir-busqueda","Describir lo que busco y negociar condiciones","Puedo explicar durante dos minutos qué casa o servicio busco y por qué, y negociar con un interlocutor lo que es imprescindible y lo que no.",["b1.fun.w07-pedir-requisitos"]],
  [7,"fun","w07-pedir-requisitos","Pedir algo con requisitos y justificarlo","Puedo pedir un objeto, una vivienda o un servicio diciendo qué características debe tener y para qué lo quiero.",["b1.gram.g099","b1.gram.g100"]],
  [7,"disc","w07-requisito-finalidad","Encadenar requisito y finalidad","Puedo organizar una petición en orden (lo que busco, lo que conozco, para qué lo necesito) con relativas y conectores de finalidad sin repetir siempre «para».",["b1.gram.g099","b1.gram.g100"]],
  [8,"gram","g101","Conceder un hecho real con «aunque» + indicativo","Puedo reconocer un obstáculo real con «aunque» + indicativo, delante o detrás de la idea principal, y alternarlo con «pero», «sin embargo», «aun así» y «a pesar de».",["b1.gram.g094"],{"related":["/gramatica/concesivas-iniciales-aunque-indicativo"]}],
  [8,"gram","g102","Condiciones reales: si + presente","Puedo plantear condiciones posibles con «si» + presente de indicativo y una consecuencia en presente, futuro, «ir a», imperativo o «poder / tener que», sin usar futuro ni subjuntivo detrás de «si».",["b1.gram.g098"],{"related":["/gramatica/condiciones-reales-si-presente-y-futuro"]}],
  [8,"gram","g103","Condicional simple: cortesía, consejo e hipótesis","Puedo formar el condicional regular e irregular y usarlo para pedir con cortesía, aconsejar («yo que tú…», «deberías…»), imaginar y contar un futuro visto desde el pasado.",["b1.gram.g090"],{"related":["/sistema-verbal/condicional-simple-indicativo"]}],
  [8,"voc","w08-correr-entrenar","Correr y entrenar para una carrera","Puedo hablar de un plan de entrenamiento con palabras como inscribirse, dorsal, ritmo, tirada larga, avituallamiento, agujetas y cruzar la meta.",["b1.gram.g102"]],
  [8,"pron","w08-ria-ia","Condicional o imperfecto: «-ría» frente a «-ía»","Puedo distinguir de oído «correría» de «corría» y «saldría» de «salía», y pronunciar el hiato «-rí-a» con el acento en la «í».",["b1.gram.g103"]],
  [8,"lis","w08-consejos-entrenadora","Los consejos de una entrenadora","Puedo seguir una conversación en la que una entrenadora aconseja a una principiante y separar condiciones, consejos y obstáculos aceptados.",["b1.gram.g101","b1.gram.g102","b1.gram.g103"]],
  [8,"read","w08-guia-primera-carrera","Guía para una primera carrera","Puedo entender la guía de un club de corredores para principiantes e identificar qué pasa en cada situación posible.",["b1.gram.g102","b1.gram.g103"]],
  [8,"wri","w08-correo-consejos","Correo de consejos ante un reto","Puedo escribir un correo de unas 150 palabras para animar y aconsejar a alguien que duda ante un reto, reconociendo sus dificultades.",["b1.fun.w08-animar-aconsejar","b1.disc.w08-obstaculo-decision"]],
  [8,"spk","w08-plan-negociado","Aconsejar y negociar un plan","Puedo dar consejos durante dos minutos sobre un reto personal y negociar con cortesía un plan con un interlocutor que pone objeciones.",["b1.fun.w08-animar-aconsejar"]],
  [8,"fun","w08-animar-aconsejar","Animar, aconsejar y pedir con cortesía","Puedo animar a alguien reconociendo los obstáculos, darle consejos según las condiciones posibles y pedir algo con «¿podrías…?» o «me gustaría…».",["b1.gram.g101","b1.gram.g102","b1.gram.g103"]],
  [8,"disc","w08-obstaculo-decision","Del obstáculo a la decisión","Puedo organizar una argumentación breve que presenta un obstáculo, lo concede con «aunque» o «a pesar de» y llega a una decisión con «aun así» o «sin embargo».",["b1.gram.g101"]],
  [9,"gram","g104","Condiciones y consejos para resolver situaciones reales","Puedo organizar un plan con alternativas («si…, …; si no, …»), distinguir una condición, un plan acordado y una regla, y aconsejar sin dar órdenes diciendo lo que yo haría.",["b1.gram.g102","b1.gram.g103"],{"related":["/condicionales-b1"]}],
  [9,"gram","g105","Por y para: causa, propósito, plazo, destinatario","Puedo elegir «por» para la causa, el recorrido, el medio, el intercambio y el precio, y «para» para el objetivo, el destinatario, el destino y el plazo.",["b1.gram.g099"],{"related":["/gramatica/por-para-razones-objetivos"]}],
  [9,"voc","w09-naturaleza-voluntariado","Naturaleza y voluntariado","Puedo hablar de un voluntariado ambiental con palabras como parque nacional, desove, nido, playa de anidación, guardaparques, temporada de lluvias y huella ecológica.",["b1.gram.g105"]],
  [9,"pron","w09-por-para-rapido","«Por», «para» y «pa’» en el habla rápida","Puedo reconocer «por», «para» y la forma coloquial «pa’» en el habla rápida y pronunciar «para» y «por» sin perder la vocal ni la erre final.",["b1.gram.g105"]],
  [9,"lis","w09-reunion-voluntarios","Reunión de salida de un voluntariado","Puedo seguir la reunión en la que una coordinadora explica a los voluntarios el viaje y las normas, y anotar las alternativas, las reglas y los consejos.",["b1.gram.g104","b1.gram.g105"]],
  [9,"read","w09-normas-proyecto","Normas y consejos de un proyecto ambiental","Puedo entender el documento de bienvenida de un proyecto de conservación y distinguir lo que es obligatorio de lo que solo se aconseja.",["b1.gram.g104","b1.gram.g105"]],
  [9,"wri","w09-plan-alternativas","Plan de viaje con alternativas","Puedo escribir un mensaje de unas 150 palabras que organice un viaje en grupo con un plan A y un plan B, normas claras y consejos.",["b1.fun.w09-resolver-imprevistos","b1.disc.w09-plan-alternativo"]],
  [9,"spk","w09-resolver-problema","Resolver un imprevisto hablando","Puedo explicar durante dos minutos qué haremos según distintas condiciones y responder a las preguntas de un interlocutor que propone otra solución.",["b1.fun.w09-resolver-imprevistos"]],
  [9,"fun","w09-resolver-imprevistos","Prever imprevistos y proponer soluciones","Puedo anticipar problemas de un viaje o de un proyecto y proponer qué hacer en cada caso, con razones y destinatarios claros.",["b1.gram.g104","b1.gram.g105"]],
  [9,"disc","w09-plan-alternativo","Plan principal y plan alternativo","Puedo presentar un plan principal, una alternativa con «si no» o «en ese caso» y una recomendación final, en un texto ordenado.",["b1.gram.g104"]],
  [10,"gram","g106","Empezar a, ponerse a, echarse a","Puedo contar cómo empieza una acción con «empezar / comenzar a» (inicio neutro), «ponerse a» (inicio decidido o repentino) y «echarse a» (reír, llorar, correr), y colocar bien los pronombres.",["b1.gram.g086"],{"related":["/gramatica/perifrasis-incoativas-empezar-a-ponerse-a"]}],
  [10,"gram","g107","Seguir + gerundio y soler + infinitivo","Puedo decir que una acción continúa con «seguir + gerundio» o no ha empezado con «seguir sin + infinitivo», y hablar de costumbres con «soler + infinitivo».",["b1.gram.g106"],{"related":["/empezar-seguir-repetir-dejar-de-hacer"]}],
  [10,"voc","w10-emprender-barrio","Emprender un pequeño negocio de barrio","Puedo contar cómo nace un pequeño negocio con palabras como local, alquilar, socio, clientela, facturar, sacar adelante y salir a flote.",["b1.gram.g106"]],
  [10,"pron","w10-gerundio-vocal","El gerundio: -ando, -iendo, -yendo y el cambio de vocal","Puedo oír y pronunciar los gerundios con cambio vocálico (durmiendo, pidiendo, diciendo) y con «y» (leyendo, oyendo), con el acento en «-AN-» o «-IEN-».",["b1.gram.g107"]],
  [10,"lis","w10-podcast-libreria","Entrevista de radio a una emprendedora","Puedo seguir una entrevista de radio en la que una emprendedora cuenta cómo empezó, qué sigue haciendo y qué planes tiene, y reconocer en ella las estructuras de las semanas 6 a 10.",["b1.gram.g106","b1.gram.g107"]],
  [10,"read","w10-perfil-diario","Perfil de una vecina en el diario local","Puedo entender un perfil periodístico sobre un proyecto de barrio y seguir la línea temporal: cómo empezó, qué continúa y qué vendrá.",["b1.gram.g106","b1.gram.g107"]],
  [10,"wri","w10-correo-un-ano-despues","Correo: un año después de empezar algo","Puedo escribir un correo de unas 170 palabras que cuente cómo empecé una actividad, qué sigo haciendo, qué planes tengo y qué aconsejaría, usando la gramática de las semanas 6 a 10.",["b1.disc.w10-linea-temporal","b1.rev.w10-repaso-semanas-6-9"]],
  [10,"spk","w10-contar-proyecto","Contar un proyecto y responder preguntas","Puedo contar durante dos minutos y medio cómo empecé un proyecto personal y responder a las preguntas de un interlocutor sobre lo que sigo haciendo y lo que haré.",["b1.fun.w10-contar-trayectoria"]],
  [10,"fun","w10-contar-trayectoria","Contar una trayectoria personal","Puedo contar el inicio, la continuidad y los planes de una actividad personal, valorando lo ocurrido y explicando para qué la hago.",["b1.gram.g106","b1.gram.g107","b1.gram.g097"]],
  [10,"disc","w10-linea-temporal","Ordenar una historia en el tiempo","Puedo organizar un relato en tres tiempos (cómo empezó, qué sigue igual, qué vendrá) con marcadores y perífrasis, sin perder al lector.",["b1.gram.g106","b1.gram.g107","b1.gram.g098"]],
  [10,"rev","w10-repaso-semanas-6-9","Repaso integrado de las semanas 6 a 9","Puedo combinar en un mismo texto el perfecto de subjuntivo, las temporales con futuro, la finalidad, las relativas, «aunque», «si» + presente, el condicional y «por / para».",["b1.gram.g097","b1.gram.g098","b1.gram.g099","b1.gram.g100","b1.gram.g101","b1.gram.g102","b1.gram.g103","b1.gram.g104","b1.gram.g105"]],
  [11,"gram","g108","Acabar de, terminar de, dejar de: cómo termina una acción","Puedo decir lo que acabo de hacer, distinguir terminar una tarea de dejar de hacer algo, animar con «no dejes de» y contar hasta dónde llegó o cómo acabó una historia con «llegar a» y «acabar + gerundio».",["b1.gram.g106","b1.gram.g107"],{"related":["/gramatica/perifrasis-terminativas-acabar-de-dejar-de"]}],
  [11,"gram","g109","Volver a + infinitivo: repetir y retomar","Puedo contar lo que se repite o se retoma con «volver a + infinitivo» en cualquier tiempo, colocar bien los pronombres y prometer o advertir con «no volver a».",["b1.gram.g108"],{"related":["/gramatica/volver-a-infinitivo-y-repeticion"]}],
  [11,"voc","w11-habitos-digitales","Hábitos digitales y desconexión","Puedo hablar de mi relación con el móvil y las redes con palabras como desconectar, enganchado, notificaciones, pantalla, el reto, la recaída y quitarse un hábito.",["b1.gram.g108"]],
  [11,"pron","w11-acento-presente-pasado","Acabo / acabó, dejo / dejó, vuelvo / volvió","Puedo distinguir de oído «acabo de» y «acabó de», «dejo de» y «dejó de», y pronunciar la sílaba tónica que separa el presente del pasado.",["b1.gram.g108","b1.gram.g109"]],
  [11,"lis","w11-charla-teteria","Charla en una tetería sobre un reto sin redes","Puedo seguir una conversación informal en la que alguien cuenta qué ha dejado de hacer, qué ha vuelto a hacer y qué acaba de terminar, y anotar los cambios.",["b1.gram.g108","b1.gram.g109"]],
  [11,"read","w11-blog-dia-31","Entrada de blog: el día después de un reto","Puedo entender una entrada de blog personal sobre un mes sin redes sociales y distinguir los hábitos abandonados, los retomados y los resultados.",["b1.gram.g108","b1.gram.g109"]],
  [11,"wri","w11-balance-cambio","Balance de un cambio de hábito","Puedo escribir un texto de unas 150 palabras que cuente un cambio de hábito: qué acabo de conseguir, qué dejé de hacer, qué volví a hacer y qué no quiero volver a hacer.",["b1.fun.w11-contar-cambios","b1.disc.w11-antes-despues"]],
  [11,"spk","w11-contar-reto","Contar un reto personal y responder preguntas","Puedo contar durante dos minutos un reto personal y responder a las preguntas de un interlocutor sobre lo que dejé de hacer y lo que volví a hacer.",["b1.fun.w11-contar-cambios"]],
  [11,"fun","w11-contar-cambios","Contar cambios de hábitos","Puedo explicar qué hábito he abandonado, cuál he retomado y qué resultado he obtenido, y hacer una promesa o dar una advertencia sobre el futuro.",["b1.gram.g108","b1.gram.g109"]],
  [11,"disc","w11-antes-despues","Organizar un antes y un después","Puedo ordenar un relato de cambio en tres momentos (lo que hacía, lo que dejé o retomé, cómo acabó) con perífrasis y marcadores temporales.",["b1.gram.g108"]],
  [12,"gram","g110","Verbos con preposición fija: a, de, en, con","Puedo usar verbos que siempre llevan la misma preposición (acostumbrarse a, tratar de, darse cuenta de, pensar en, confiar en, contar con, soñar con), mantenerla delante de «que» y en las preguntas, y evitar el dequeísmo y el queísmo.",["a2.gram.g052","b1.gram.g109"],{"related":["/gramatica/acostumbrarse-a-tratar-de-pensar-en"]}],
  [12,"gram","g238","Verbos de cambio: hacerse, volverse, convertirse en, llegar a ser","Puedo contar cómo cambian las personas y los lugares eligiendo entre hacerse (decisión o proceso), volverse (cambio de carácter), convertirse en (transformación), llegar a ser (meta con esfuerzo) y pasar a ser (cambio de categoría).",["a2.gram.g061","b1.gram.g110"],{"related":["/gramatica/verbos-de-cambio-hacerse-volverse-convertirse-en"]}],
  [12,"voc","w12-artesania-cambio-vida","Artesanía y cambio de vida","Puedo hablar de un oficio artesanal y de un cambio de vida con palabras como paja toquilla, tejer, el taller, el aprendiz, el oficio, dar un giro y ganarse la vida.",["b1.gram.g238"]],
  [12,"pron","w12-preposicion-enlazada","La preposición que se pierde al enlazar","Puedo oír y pronunciar la preposición que se une a la vocal anterior («me acostumbré‿a», «pienso‿en‿ella», «se convirtió‿en») sin comérmela al hablar ni al escribir.",["b1.gram.g110"]],
  [12,"lis","w12-visita-taller","Visita a un taller de sombreros","Puedo seguir una conversación en la que una artesana cuenta cómo cambió de vida, a qué se acostumbró y en qué se convirtió su casa, y anotar los cambios.",["b1.gram.g110","b1.gram.g238"]],
  [12,"read","w12-perfil-revista","Perfil en una revista: de ingeniera a tejedora","Puedo entender un perfil de revista sobre un cambio de vida y distinguir los cambios voluntarios, los involuntarios y los que llegaron con esfuerzo.",["b1.gram.g110","b1.gram.g238"]],
  [12,"wri","w12-cambio-persona-lugar","Texto: cómo ha cambiado una persona o un lugar","Puedo escribir un texto de unas 150 palabras sobre cómo ha cambiado una persona o un lugar que conozco, con verbos de cambio y verbos con preposición.",["b1.fun.w12-describir-cambios","b1.disc.w12-antes-ahora"]],
  [12,"spk","w12-mi-cambio","Contar un cambio personal y responder preguntas","Puedo hablar durante dos minutos de cómo he cambiado yo o alguien cercano y responder a las preguntas de un interlocutor sobre lo que me costó y con qué sueño.",["b1.fun.w12-describir-cambios"]],
  [12,"fun","w12-describir-cambios","Describir cambios en personas y lugares","Puedo describir cómo ha cambiado una persona o un lugar, distinguir si el cambio fue voluntario o no, y hablar de lo que me costó acostumbrarme.",["b1.gram.g110","b1.gram.g238"]],
  [12,"disc","w12-antes-ahora","Contraste entre antes y ahora","Puedo organizar un texto que contraste cómo era algo antes y en qué se ha convertido, con marcadores como «antes», «con los años», «hoy» y «al final».",["b1.gram.g238"]],
  [13,"gram","g111","El tema delante y su pronombre","Puedo poner delante el tema del que hablo y retomarlo con lo, la, los, las, le o les («El pescado lo compré yo», «A los proveedores les escribí ayer»), destacar con «a mí», «a ella» y responder con «lo es».",["a2.gram.g064","a2.gram.g065"],{"related":["/gramatica/pronombres-personales-y-doble-mencion-tematica"]}],
  [13,"gram","g112","Relativos quien, el que, el cual","Puedo identificar personas y cosas con «quien», «el que / la que» (también después de preposición y sin nombre delante), reconocer «el cual» en textos formales y distinguir con comas «solo algunos» de «todos».",["a2.gram.g066","b1.gram.g100"],{"related":["/gramatica/relativos-quien-el-que-el-cual"]}],
  [13,"gram","g113","Lo que, lo de y lo + adjetivo","Puedo presentar ideas y temas sin nombrarlos con «lo que» («Lo que me preocupa es…»), «lo de» («lo del pedido») y «lo + adjetivo» («lo bueno es que…»).",["a2.gram.g067","b1.gram.g112"],{"related":["/gramatica/lo-que-y-lo-de-referencias"]}],
  [13,"voc","w13-cocina-feria","Cocina profesional y feria gastronómica","Puedo hablar de la organización de una cocina y de una feria gastronómica con palabras como el puesto, el proveedor, la brigada, el pedido, la mise en place, el emplatado y agotar existencias.",["b1.gram.g111"]],
  [13,"pron","w13-comas-pausas","Pausas que cambian el sentido","Puedo oír y hacer la pausa que separa una relativa explicativa («Los cocineros, que llegaron tarde, …») de una especificativa, y la pausa tras el tema que va delante («El pescado, lo compré yo»).",["b1.gram.g112","b1.gram.g111"]],
  [13,"lis","w13-reunion-cocina","Reunión en la cocina antes de una feria","Puedo seguir la conversación en la que una cocinera y su ayudante repasan tareas pendientes, personas y problemas, y anotar qué está hecho, quién se encarga y qué preocupa.",["b1.gram.g111","b1.gram.g112","b1.gram.g113"]],
  [13,"read","w13-cronica-feria","Crónica de una feria gastronómica","Puedo entender una crónica periodística sobre una feria de comida y relacionar a cada persona con lo que hizo y lo que opina.",["b1.gram.g112","b1.gram.g113"]],
  [13,"wri","w13-informe-equipo","Mensaje de puesta al día a un equipo","Puedo escribir un mensaje de unas 150 palabras que ponga al día a un equipo: qué está hecho, quién se encarga de qué, lo que preocupa y lo bueno de la situación.",["b1.fun.w13-poner-al-dia","b1.disc.w13-temas-ordenados"]],
  [13,"spk","w13-poner-al-dia-oral","Poner al día a alguien y responder preguntas","Puedo explicar durante dos minutos cómo va un proyecto y responder a las preguntas de un interlocutor que vuelve después de unos días fuera.",["b1.fun.w13-poner-al-dia"]],
  [13,"fun","w13-poner-al-dia","Poner al día sobre tareas y personas","Puedo informar de tareas hechas y pendientes, identificar a las personas responsables y destacar lo importante sin repetir nombres.",["b1.gram.g111","b1.gram.g112","b1.gram.g113"]],
  [13,"disc","w13-temas-ordenados","Ordenar un mensaje por temas","Puedo organizar un mensaje por temas, presentando cada uno delante («Lo de las mesas…», «Los postres…») y retomándolo con un pronombre.",["b1.gram.g111","b1.gram.g113"]],
  [14,"gram","g114","Matizar con ni… ni, sin embargo, pero y aunque","Puedo descartar dos cosas con «ni… ni», presentar un contrapeso con «sin embargo» o «pero», y añadir un matiz breve con «aunque», sabiendo que lo que va al final pesa más.",["b1.gram.g101"],{"related":["/pero-hay-un-matiz"]}],
  [14,"gram","g115","Explicar causas: porque, como, ya que, puesto que","Puedo explicar causas con el conector adecuado a la posición y al registro: es que, porque, como, ya que, puesto que, dado que, debido a, a causa de, gracias a y por culpa de.",["a2.gram.g077","b1.gram.g105"],{"related":["/gramatica/causales-ya-que-puesto-que-como"]}],
  [14,"voc","w14-viajes-resenas","Excursiones, alojamientos y reseñas","Puedo hablar de una excursión y valorar un alojamiento con palabras como el trayecto, el mirador, el mal de altura, la cancelación, el reembolso, la reseña y la relación calidad-precio.",["b1.gram.g114"]],
  [14,"pron","w14-como-porque-tilde","Como / cómo, porque / por qué","Puedo distinguir de oído «como» causal (átono) de «cómo» interrogativo (tónico), y «porque» de «por qué», y marcar con la voz la pausa de «sin embargo».",["b1.gram.g115"]],
  [14,"lis","w14-llamada-agencia","Llamada a una agencia por una excursión cancelada","Puedo seguir una llamada en la que una agencia explica las causas de una cancelación y un cliente valora el viaje con matices, y anotar causas, ventajas y contrapesos.",["b1.gram.g114","b1.gram.g115"]],
  [14,"read","w14-resena-colca","Reseña de una excursión al Colca","Puedo entender una reseña de viaje con matices y distinguir lo que el autor descarta, lo que valora, lo que critica y las causas que da.",["b1.gram.g114","b1.gram.g115"]],
  [14,"wri","w14-resena-matizada","Reseña matizada de un lugar","Puedo escribir una reseña de unas 150 palabras sobre un alojamiento, un restaurante o una excursión, con matices y causas claras.",["b1.fun.w14-valorar-con-matices","b1.disc.w14-equilibrio-opinion"]],
  [14,"spk","w14-reclamar-explicar","Explicar un problema y responder a una reclamación","Puedo explicar durante dos minutos qué salió bien y qué salió mal en un viaje, con causas, y responder a las preguntas de un interlocutor que pide aclaraciones.",["b1.fun.w14-valorar-con-matices"]],
  [14,"fun","w14-valorar-con-matices","Valorar con matices y justificar","Puedo dar una opinión equilibrada sobre un servicio, descartar problemas, reconocer ventajas, señalar un contrapeso y explicar las causas.",["b1.gram.g114","b1.gram.g115"]],
  [14,"disc","w14-equilibrio-opinion","Una opinión equilibrada","Puedo ordenar una valoración en dos partes (lo positivo y el contrapeso) y decidir qué idea dejo al final para que pese más.",["b1.gram.g114"]],
  [15,"gram","g116","Consecuencias: así que, por eso, de modo que","Puedo contar las consecuencias de un hecho con así que, por eso o entonces en la conversación, y con por lo tanto o en consecuencia en un texto formal, y distinguir «de modo que» + indicativo (resultado) de + subjuntivo (finalidad).",["b1.gram.g115","b1.gram.g099"],{"related":["/gramatica/consecutivas-asi-que-por-eso-de"]}],
  [15,"gram","g117","Argumentar: además, incluso, en cambio","Puedo sumar argumentos (además, también, encima, es más), intensificar (incluso, hasta, ni siquiera), comparar dos posturas (en cambio, mientras que) y corregir una idea con «no… sino» frente a «pero».",["b1.gram.g114"],{"related":["/gramatica/conectores-argumentativos-ademas-incluso-en-cambio"]}],
  [15,"voc","w15-mudanza-ciudad","Mudarse de ciudad: ventajas e inconvenientes","Puedo debatir sobre cambiar de ciudad con palabras como la oferta de trabajo, el coste de vida, el clima, la altura, echar raíces, el arraigo y pesar más.",["b1.gram.g117"]],
  [15,"pron","w15-asi-que-sino","«¿Así que…?» y «sino / si no»","Puedo distinguir por la entonación «así que» como conclusión de «¿así que…?» como pregunta, y pronunciar «sino» (una palabra, átona) frente a «si no» (con «no» tónico).",["b1.gram.g116","b1.gram.g117"]],
  [15,"lis","w15-debate-familiar","Debate familiar sobre una mudanza","Puedo seguir una conversación familiar en la que se suman argumentos, se comparan posturas y se sacan consecuencias, y reconocer en ella la gramática de las semanas 11 a 15.",["b1.gram.g116","b1.gram.g117"]],
  [15,"read","w15-columna-quedarse","Columna de opinión: por qué me quedo","Puedo entender una columna de opinión, seguir sus argumentos y sus consecuencias, y distinguir la postura de la autora de la que critica.",["b1.gram.g116","b1.gram.g117"]],
  [15,"wri","w15-texto-argumentativo","Texto de opinión con argumentos y consecuencias","Puedo escribir un texto de unas 170 palabras que defienda una decisión con argumentos ordenados, consecuencias y matices, usando la gramática de las semanas 11 a 15.",["b1.disc.w15-argumento-ordenado","b1.rev.w15-semanas-11-15"]],
  [15,"spk","w15-defender-decision","Defender una decisión y responder objeciones","Puedo defender durante dos minutos y medio una decisión importante y responder a las objeciones de un interlocutor, corrigiendo ideas falsas y sacando conclusiones.",["b1.fun.w15-argumentar-decidir"]],
  [15,"fun","w15-argumentar-decidir","Argumentar para tomar una decisión","Puedo presentar argumentos a favor y en contra, compararlos, sacar consecuencias y llegar a una decisión justificada.",["b1.gram.g116","b1.gram.g117","b1.gram.g115"]],
  [15,"disc","w15-argumento-ordenado","Un texto argumentativo ordenado","Puedo ordenar un texto de opinión con una tesis, argumentos enlazados (en primer lugar, además, incluso, en cambio) y una conclusión con «por lo tanto».",["b1.gram.g116","b1.gram.g117","b1.gram.g114"]],
  [15,"rev","w15-semanas-11-15","Repaso integrado de las semanas 11 a 15","Puedo combinar en un mismo texto las perífrasis de final y repetición, los verbos con preposición y de cambio, el tema delante, los relativos, «lo que» y «lo de», los matices, las causas, las consecuencias y los conectores argumentativos.",["b1.gram.g108","b1.gram.g109","b1.gram.g110","b1.gram.g238","b1.gram.g111","b1.gram.g112","b1.gram.g113","b1.gram.g114","b1.gram.g115"]],
  [16,"gram","g118","Discurso referido introductorio: dijo que / pidió que","Puedo contar en pasado lo que alguien dijo, preguntó o pidió, haciendo retroceder los tiempos (presente → imperfecto, pasado → pluscuamperfecto, futuro → condicional), cambiando personas y referencias de tiempo y lugar, y usando «me pidió que» + viniera, llamara o hiciera.",["b1.gram.g087","b1.gram.g103","a2.gram.g083"],{"related":["/gramatica/discurso-referido-introductorio-dijo-que-pidio"]}],
  [16,"gram","g119","Se pasivo y se impersonal introductorio","Puedo explicar lo que se hace sin decir quién lo hace, con «se» + verbo que concuerda con la cosa (se venden platos) o en singular cuando no hay cosa (se vive bien, se prohíbe fumar, se busca a los dueños), y usar alternativas como «dicen que» o «uno».",["a2.gram.g076"],{"related":["/gramatica/se-pasivo-y-se-impersonal-introductorio"]}],
  [16,"voc","w16-taller-artesania","Un taller artesanal y un encargo","Puedo hablar de un taller artesanal y de un encargo con palabras como barro, torno, horno, esmalte, anticipo, muestra, plazo de entrega y envío.",["b1.gram.g119"]],
  [16,"pron","w16-pregunta-referida","Entonación de la pregunta directa y de la pregunta contada","Puedo distinguir por la entonación una pregunta directa (tono que sube) de una pregunta contada con «preguntó si» (tono que baja) y producir las dos.",["b1.gram.g118"]],
  [16,"lis","w16-encargo-taller","Conversación sobre el encargo de una clienta","Puedo seguir una conversación en la que una aprendiz cuenta lo que dijo, preguntó y pidió una clienta, y cómo se hará el pedido.",["b1.gram.g118","b1.gram.g119"]],
  [16,"read","w16-como-se-hace","Página web: cómo se hace una pieza artesanal","Puedo entender un texto que explica un proceso artesanal con «se» y que recoge lo que contaron y preguntaron sus visitantes.",["b1.gram.g118","b1.gram.g119"]],
  [16,"wri","w16-correo-reunion","Correo para contar una reunión","Puedo escribir un correo de unas 150 palabras que cuente a alguien qué se dijo, qué se preguntó y qué se pidió en una reunión, y cómo se va a organizar lo decidido.",["b1.fun.w16-transmitir-mensajes","b1.disc.w16-voces-y-procesos"]],
  [16,"spk","w16-contar-conversacion","Contar una conversación importante","Puedo contar durante dos minutos una conversación importante y responder a las preguntas de un interlocutor que no estuvo presente, aclarando quién dijo cada cosa.",["b1.fun.w16-transmitir-mensajes"]],
  [16,"fun","w16-transmitir-mensajes","Transmitir mensajes y recados","Puedo transmitir recados, preguntas y peticiones de otras personas sin cambiar su sentido.",["b1.gram.g118"]],
  [16,"disc","w16-voces-y-procesos","Distinguir quién habla y qué se hace","Puedo organizar un texto que alterna las palabras de distintas personas con la descripción de procesos impersonales, sin que el lector pierda quién dijo qué.",["b1.gram.g118","b1.gram.g119"]],
  [17,"gram","g120","Estar + participio para estados resultantes","Puedo describir el estado que deja una acción con «estar» + participio concordado (la puerta está cerrada, las maletas estaban hechas), distinguirlo de «haber» + participio y de «estar» + gerundio, y usar «quedarse», «tener» y «llevar» + participio.",["a2.gram.g046","b1.gram.g087"],{"related":["/gramatica/estar-participio-para-estados-resultantes"]}],
  [17,"gram","g121","Diferencia entre ser + participio y estar + participio","Puedo entender «ser» + participio como una acción con fecha o con autor (fue construido en 1611 por…), distinguirlo de «estar» + participio como estado (hoy está restaurado) y reformularlo en activa o con «se».",["b1.gram.g119","b1.gram.g120"],{"related":["/gramatica/diferencia-entre-ser-participio-y-estar"]}],
  [17,"voc","w17-alojamiento-edificio","Alojamiento y edificios históricos","Puedo hablar del estado de un alojamiento y de la historia de un edificio con palabras como inventario, fianza, desperfecto, persiana, claustro, fachada, obras y rehabilitar.",["b1.gram.g120"]],
  [17,"pron","w17-participio-ado","El participio en -ado: forma cuidada y relajada","Puedo reconocer la pronunciación relajada de «-ado» («cansao») frecuente en España y pronunciar los participios con una «d» suave adecuada a cualquier registro.",["b1.gram.g120"]],
  [17,"lis","w17-entrada-residencia","Revisión de una habitación con la gerente de una residencia","Puedo seguir una conversación en la que se revisa el estado de una habitación con el inventario y se cuenta la historia del edificio, y anotar qué está bien, qué está roto y qué pasó.",["b1.gram.g120","b1.gram.g121"]],
  [17,"read","w17-historia-edificio","Historia de un edificio histórico","Puedo entender un texto que cuenta la historia de un edificio con «ser» + participio y describe cómo estaba y cómo está con «estar» + participio.",["b1.gram.g120","b1.gram.g121"]],
  [17,"wri","w17-correo-estado-habitacion","Correo sobre el estado de una habitación","Puedo escribir un correo de unas 150 palabras que describa cómo encontré una habitación, cómo está ahora, qué llevo hecho y qué falta por arreglar.",["b1.fun.w17-revisar-estado","b1.disc.w17-antes-y-ahora"]],
  [17,"spk","w17-describir-estado","Describir cómo estaba y cómo está un lugar","Puedo describir durante dos minutos cómo estaba un lugar, qué pasó y cómo está ahora, y responder a las preguntas de un interlocutor al reclamar un desperfecto.",["b1.fun.w17-revisar-estado"]],
  [17,"fun","w17-revisar-estado","Revisar y reclamar el estado de algo","Puedo comprobar el estado de un alojamiento, dejar constancia de lo que estaba roto y pedir que lo arreglen.",["b1.gram.g120"]],
  [17,"disc","w17-antes-y-ahora","Contar el antes y el ahora de un lugar","Puedo organizar un texto que alterna lo que pasó (acciones) con cómo estaba y cómo está un lugar (estados), sin mezclar los dos planos.",["b1.gram.g120","b1.gram.g121"]],
  [18,"gram","g237","Ser y estar con adjetivos que cambian de significado","Puedo elegir «ser» o «estar» con adjetivos cuyo significado cambia (listo, rico, aburrido, malo, verde, despierto, atento, seguro, orgulloso, interesado) y usar sus preposiciones con «estar» (orgulloso de, seguro de, interesado en, listo para).",["a2.gram.g075","b1.gram.g120"],{"related":["/gramatica/ser-y-estar-con-adjetivos-que-cambian-de-significado"]}],
  [18,"gram","g122","Orden de pronombres y clíticos más complejo","Puedo combinar dos pronombres en su orden (se lo, te la, me los), cambiar «le» por «se» y colocarlos delante del verbo conjugado, después de «no» o pegados al imperativo, al infinitivo y al gerundio con tilde, también con perífrasis.",["a2.gram.g064","a2.gram.g065","b1.gram.g103"],{"related":["/gramatica/orden-de-pronombres-y-cliticos-mas"]}],
  [18,"gram","g123","Concordancia compleja con colectivos y cantidades","Puedo concordar el verbo con colectivos (la gente dice), con cantidades + de + plural (la mitad votó / votaron), con «cada uno de», con «ni… ni» y con sujetos coordinados, y usar «haber» de existencia siempre en singular.",["b1.gram.g114"],{"related":["/gramatica/concordancia-compleja-con-colectivos-y-cantidades"]}],
  [18,"voc","w18-fiesta-familiar","Una fiesta familiar","Puedo organizar y contar una fiesta familiar con palabras como invitados, brindis, discurso, asado, parrilla, torta, soplar las velas y hacer una vaquita.",["b1.gram.g123"]],
  [18,"pron","w18-pronombres-pegados","Pronombres pegados al verbo: la sílaba fuerte","Puedo reconocer y pronunciar formas como «dáselo», «decírselo» o «preparándosela» con la fuerza en la sílaba del verbo y los pronombres átonos.",["b1.gram.g122"]],
  [18,"lis","w18-plan-sorpresa","Reunión para preparar una fiesta sorpresa","Puedo seguir una conversación entre primos que preparan una fiesta sorpresa y anotar quién sabe qué, quién se encarga de cada cosa y cuándo se da el regalo.",["b1.gram.g237","b1.gram.g122","b1.gram.g123"]],
  [18,"read","w18-cronica-cumpleanos","Crónica de un cumpleaños en un boletín","Puedo entender la crónica de una fiesta en un boletín de barrio e interpretar los adjetivos con «ser» y «estar», los pronombres y la concordancia con grupos.",["b1.gram.g237","b1.gram.g122","b1.gram.g123"]],
  [18,"wri","w18-cronica-fiesta","Crónica breve de una celebración","Puedo escribir una crónica de unas 150 palabras sobre una celebración, con cifras y decisiones del grupo bien concordadas, descripciones precisas y pronombres sin repeticiones.",["b1.fun.w18-organizar-en-grupo","b1.disc.w18-informar-decisiones"]],
  [18,"spk","w18-organizar-celebracion","Contar y organizar una celebración","Puedo contar durante dos minutos cómo se organizó una celebración y negociar con un interlocutor cómo mantener una sorpresa en secreto.",["b1.fun.w18-organizar-en-grupo"]],
  [18,"fun","w18-organizar-en-grupo","Organizar algo en grupo","Puedo repartir tareas, pedir discreción y explicar quién da qué a quién en la organización de un evento.",["b1.gram.g122","b1.gram.g123"]],
  [18,"disc","w18-informar-decisiones","Informar de lo que decidió un grupo","Puedo informar de una reunión o una votación con cifras, mayorías y decisiones, manteniendo la concordancia y sin repetir nombres.",["b1.gram.g122","b1.gram.g123"]],
  [19,"gram","g124","Elipsis y reformulación: evitar repeticiones","Puedo evitar repeticiones omitiendo un nombre conocido (la gris, la de Tomás, la que tiene ruedas), usar posesivos largos (el mío, la suya) o «el de» + persona, explicar con una aposición entre comas y seleccionar con un modificador sin comas.",["b1.gram.g112","b1.gram.g113"],{"related":["/decir-mas-sin-repetir"]}],
  [19,"gram","g125","Narración de anécdotas con marcadores","Puedo contar una anécdota con gancho (resulta que, ¿a que no sabes…?), escena en imperfecto, hechos en indefinido, sorpresa (de repente, justo cuando), lo anterior en pluscuamperfecto y cierre (al final, por fin, menos mal que), y reaccionar a la de otra persona.",["b1.gram.g086","b1.gram.g087"],{"related":["/gramatica/narracion-de-anecdotas-con-marcadores"]}],
  [19,"voc","w19-viaje-imprevistos","Imprevistos de viaje","Puedo contar imprevistos de viaje con palabras como cinta de equipaje, etiqueta, facturar, puerta de embarque, confundirse de maleta, perder el vuelo y darse cuenta de.",["b1.gram.g125"]],
  [19,"pron","w19-entonacion-relato","La entonación del relato","Puedo reconocer y usar el tono suspendido que anuncia que la historia sigue, el tono final que la cierra y el tono más bajo de las aposiciones.",["b1.gram.g124","b1.gram.g125"]],
  [19,"lis","w19-anecdota-aeropuerto","Anécdota de una maleta cambiada","Puedo seguir la anécdota que una persona cuenta a un compañero, con las reacciones de quien escucha, y reconstruir la escena, la sorpresa y el final.",["b1.gram.g124","b1.gram.g125"]],
  [19,"read","w19-blog-anecdota","Anécdota de viaje en un blog","Puedo entender una anécdota escrita en un blog, identificar sus partes y seguir a quién se refieren las formas sin nombre.",["b1.gram.g124","b1.gram.g125"]],
  [19,"wri","w19-contar-anecdota","Escribir una anécdota de viaje","Puedo escribir una anécdota de unas 150 palabras con escena, sorpresa y cierre, presentando a las personas con aposiciones y sin repeticiones innecesarias.",["b1.fun.w19-reaccionar-relato","b1.disc.w19-estructura-anecdota"]],
  [19,"spk","w19-anecdota-oral","Contar una anécdota oralmente","Puedo contar una anécdota durante dos minutos y responder a las preguntas y reacciones de un interlocutor sin perder el hilo.",["b1.fun.w19-reaccionar-relato"]],
  [19,"fun","w19-reaccionar-relato","Reaccionar ante un relato","Puedo mostrar sorpresa, alivio o pena ante lo que alguien cuenta y pedirle que continúe.",["b1.gram.g125"]],
  [19,"disc","w19-estructura-anecdota","Estructurar una anécdota","Puedo organizar un relato en gancho, escena, hechos, sorpresa y cierre, y mantener claras las referencias a personas y cosas sin repetir.",["b1.gram.g124","b1.gram.g125"]],
  [20,"gram","g126","Comparar hipótesis y posibilidades","Puedo comparar una opción real («si» + presente) con una imaginada (condicional), aconsejar con «yo que tú», «en tu lugar» o «sería mejor» + infinitivo, decir qué es probable (a lo mejor, puede que, lo más probable es que) y valorar ventajas e inconvenientes.",["b1.gram.g094","b1.gram.g102","b1.gram.g103"],{"related":["/gramatica/comparar-hipotesis-y-posibilidades"]}],
  [20,"gram","g127","Argumentación y toma de decisiones B1","Puedo defender una propuesta con tesis, argumentos, concesión y conclusión, eligiendo el modo después de «creo que», «no creo que», «es importante que» y «propongo que», y discrepar con cortesía para decidir en grupo.",["b1.gram.g090","b1.gram.g091","b1.gram.g093","b1.gram.g117"],{"related":["/gramatica/argumentacion-y-toma-de-decisiones-b1"]}],
  [20,"voc","w20-teatro-decisiones","Teatro y decisiones en grupo","Puedo hablar de una compañía de teatro y de una decisión colectiva con palabras como elenco, función, gira, temporada, butacas, subvención, presupuesto, someter a votación y valer la pena.",["b1.gram.g127"]],
  [20,"pron","w20-enfasis-argumentar","Énfasis y concesión en la argumentación","Puedo marcar con la voz la palabra que contrasta y la estructura de una concesión (la primera parte suspendida, la segunda con tono final), y reconocerlas al escuchar.",["b1.gram.g127"]],
  [20,"lis","w20-reunion-compania","Reunión de una compañía que decide","Puedo seguir una reunión en la que varias personas comparan dos opciones, cuentan lo que les dijeron, conceden y proponen, e identificar la decisión y los argumentos de cada una.",["b1.gram.g126","b1.gram.g127"]],
  [20,"read","w20-columna-opinion","Columna de opinión","Puedo entender una columna de opinión, distinguir su tesis, sus argumentos, sus concesiones y su propuesta, y reconocer en ella la gramática de B1.",["b1.gram.g126","b1.gram.g127"]],
  [20,"wri","w20-propuesta-razonada","Propuesta razonada antes de una votación","Puedo escribir una propuesta de unas 180 palabras en tres párrafos que compare dos opciones, valore su probabilidad, reconozca el argumento contrario y proponga una decisión, usando la gramática de las semanas 16 a 20.",["b1.disc.w20-argumento-completo","b1.rev.w20-semanas-16-20"]],
  [20,"spk","w20-defender-propuesta","Defender una propuesta y negociar","Puedo defender oralmente una propuesta durante dos minutos y medio y responder a las objeciones de un interlocutor hasta negociar una solución intermedia.",["b1.fun.w20-decidir-en-grupo"]],
  [20,"fun","w20-decidir-en-grupo","Decidir en grupo","Puedo participar en una decisión colectiva: comparar opciones, aconsejar, discrepar con cortesía y proponer una votación.",["b1.gram.g126","b1.gram.g127"]],
  [20,"disc","w20-argumento-completo","Un argumento completo","Puedo organizar un texto argumentativo en tesis, argumentos con conectores, concesión y conclusión, sin perder la claridad.",["b1.gram.g127","b1.gram.g115","b1.gram.g116"]],
  [20,"rev","w20-semanas-16-20","Repaso integrado de las semanas 16 a 20","Puedo combinar en un mismo texto el discurso referido, el «se» pasivo e impersonal, estar + participio, ser y estar con cambio de significado, dos pronombres, la concordancia con grupos, la elipsis, los marcadores de anécdota y la argumentación de B1.",["b1.gram.g118","b1.gram.g119","b1.gram.g120","b1.gram.g121","b1.gram.g237","b1.gram.g122","b1.gram.g123","b1.gram.g124","b1.gram.g125"]],
]);
